from ch13_ink import *
SO = {}
def orow(p, r, verdict, prose): SO[(p, r)] = (verdict, prose)

orow(117, 3, 'MATERIAL', f'"LEST THERE BE A WORD OF BELIAL IN YOUR HEART, SAYING" (15:9) — THIS IS WHAT IS CALLED IDOLATRY: "BELIAL" IS SAID HERE AND "BELIAL" IS SAID THERE — "MEN, SONS OF BELIAL, HAVE GONE OUT" (13:14): AS THE SONS OF BELIAL THERE ARE IDOLATRY, SO BELIAL HERE IS IDOLATRY. The row on 15:9 ({SP_(117, 3, "נאמר", "כאן", "בליעל", "ונאמר", "להלן")} "Belial is said here and Belial is said there"): I2 (checked) on the Torah\'s two seats of the word (computed) — the chapter\'s seducers lend the seventh year\'s grudge its name; THE ENGLISH\'S WRONG VERSE "(Dt.13:4)" twice for 13:14, the Hebrew\'s citation right (asserted). Fresh.')
orow(149, 1, 'MATERIAL', f'"AND IT IS TOLD YOU AND YOU HEAR AND INQUIRE DILIGENTLY" (17:4) — AND THERE IT SAYS "YOU SHALL INQUIRE AND SEARCH AND ASK DILIGENTLY" (13:15): "DILIGENTLY", "DILIGENTLY" FOR AN ANALOGY — IT TEACHES THAT THEY EXAMINE HIM WITH SEVEN INQUIRIES; THE PROBES WHENCE? "AND BEHOLD IT IS TRUE, THE THING IS CERTAIN." The row on 17:4 ({SP_(149, 1, "היטב", "היטב", "לגזרה", "שוה")} "diligently, diligently, for an analogy"): I2 (checked) — 93:6\'s analogy from the idolater\'s side (Mishnah Sanhedrin 5:1). Fresh.')
orow(149, 2, 'MATERIAL', f'IF IN THE END WE INCLUDE PROBES, WHY "INQUIRIES"? INQUIRIES — ONE SAID "I DO NOT KNOW", THEIR TESTIMONY IS VOID; PROBES — EVEN TWO SAID "WE DO NOT KNOW", IT STANDS; BOTH ALIKE WHEN THEY CONTRADICT EACH OTHER — VOID. The row on 17:4 ({SP_(149, 2, "עדותם", "בטלה")} "their testimony is void"): 93:8-9\'s table said again (Mishnah Sanhedrin 5:1-2); the English alone cites 13:15 here. Fresh.')
orow(189, 1, 'MATERIAL', f'"WHEN A MALICIOUS WITNESS RISES AGAINST A MAN TO TESTIFY REBELLION AGAINST HIM" (19:16) — "MALICIOUS" IS ONLY A ROBBER; "REBELLION" IS ONLY A TRANSGRESSION, AS IT IS SAID "FOR HE SPOKE REBELLION" (13:6) AND "THIS YEAR YOU SHALL DIE, FOR YOU HAVE SPOKEN REBELLION AGAINST THE LORD" (JEREMIAH 28:16). The row on 19:16 ({SP_(189, 1, "אין", "סרה", "אלא", "עברה")} "rebellion is only a transgression"): the noun\'s two Torah seats read by each other (computed), Hananiah\'s the third — 84:2\'s fallen prophet named by his sentence. Fresh.')
orow(190, 7, 'MATERIAL', f'"AND THE JUDGES SHALL INQUIRE DILIGENTLY" (19:18) — AND THERE IT SAYS "AND IT IS TOLD YOU … AND YOU INQUIRE DILIGENTLY" (17:4): "DILIGENTLY", "DILIGENTLY" FOR AN ANALOGY — THE SEVEN INQUIRIES; THE PROBES WHENCE? "AND BEHOLD IT IS TRUE, THE THING IS CERTAIN" (13:15). The row on 19:18 ({SP_(190, 7, "היטב", "היטב", "לגזרה", "שוה")} "diligently, diligently, for an analogy"): I2 (checked) — the third seat of the analogy, the chapter\'s clause the probes\' source at every seat. Fresh.')
orow(190, 8, 'MATERIAL', f'WHENCE THAT A WITNESS MAKES HIMSELF FALSE? "AND BEHOLD THE WITNESS IS A FALSE WITNESS" — the Hebrew row; the English\'s row at this number carries the probes\' derivation from 13:15 ("true" the inquiry, "certain" the probe). The row on 19:18 ({SP_(190, 8, "שהעד", "עושה", "עצמו", "שקר")} "that the witness makes himself false"): THE TWO FILES DIVIDE PISKA 190 DIFFERENTLY (chapter 8\'s lesson) — both texts read whole, the row counted once. Fresh.')

assert sorted(SO) == sorted(OUTSIDE) == sorted(FRESH), sorted(SO)
